"""X-MFG-36 in-house multi-stage diaphragm H2 compressor for CRYO_H2 (A-M-169). Equal pressure ratio per stage, intercooled to 35 C; stage work
W = k/(k-1) R T1/M (r^((k-1)/k) - 1)/eta_ad (ideal gas, Perry's sec. 10 [DOE_H2_COMP] with k from NIST_WEBBOOK); swept volume per stroke from the
suction flow, speed and volumetric efficiency; diaphragm diameter from a shallow spherical-cap cavity, V about pi D^2 h / 8.
Stage count: the fewest equal-ratio stages whose predicted discharge T1 (1 + (r^((k-1)/k) - 1)/eta_ad) stays at or below 135 C [API618];
intercooler duty per stage m cp (T2 - T1) [NIST_WEBBOOK]. Average power on the energy balance; sized at the peak rate (run hours). Two compressors (one standby) per the redundancy rule.
Run: python3 -m flow_graph.param.h2_compressor [--write]"""
import json, math, os, sys
from . import drivers as DR
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
GP = os.path.join(ROOT, 'flow_graph/plant_flow_graph.json')
def design(d, g):
    v = lambda k: DR.val(d, k); m_d = sum(e['rate']['value'] for e in g['edges'] if e['to_unit_id'] == 'CRYO_H2' and 'mass' in e['layers'])
    k = v('h2c_k'); T1 = v('CRYO.cold-box-asu-recovery-train.cold-box.CRYO_H2.h2c_T_suction_K'); Rm = 8.314/0.002016; x = (k - 1)/k; R = v('h2c_P2_bar')/v('h2c_P1_bar')
    Tout = lambda r: T1*(1 + (r**x - 1)/v('h2c_eta_ad'))
    n = 1
    while Tout(R**(1/n)) - 273.15 > v('h2c_T_out_max_C'): n += 1
    r = R**(1/n); w = n*k/(k - 1)*Rm*T1*(r**x - 1)/v('h2c_eta_ad')                 # J/kg, n stages
    m_pk = m_d/v('h2c_run_h')/3600; P_avg = m_d/86400*w/v('h2c_eta_motor')/1000; P_pk = m_pk*w/v('h2c_eta_motor')/1000
    st = []
    for i, Ps in enumerate([v('h2c_P1_bar')*r**j for j in range(n)]):
        rho = Ps*1e5/(Rm*T1); Vs = m_pk/rho/(v('h2c_rpm')/60*v('h2c_eta_v')); h = v('h2c_cavity_h_mm')/1000
        st.append(dict(stage=i + 1, P_in_bar=Ps, P_out_bar=Ps*r, T_out_C=Tout(r) - 273.15, intercooler_W=m_pk*v('h2c_cp_kJ_kgK')*1000*(Tout(r) - T1), swept_cm3=Vs*1e6, diaphragm_D_mm=math.sqrt(8*Vs/(math.pi*h))*1000))
    return dict(H2_kg_d=m_d, n_stages=n, T_limit_C=v('h2c_T_out_max_C'), ratio_per_stage=r, kWh_per_kg=w/3.6e6/v('h2c_eta_motor'), P_avg_kW=P_avg, P_peak_kW=P_pk, stages=st, units=v('CRYO.cold-box-asu-recovery-train.cold-box.CRYO_H2.h2c_units'),
                material='head and plates 17-4PH H1150 / 316L (hydrogen service), triple-layer 301 SS diaphragm with leak detection between layers')
def write(g, r):
    N = {n['unit_id']: n for n in g['nodes']}; E = {e['stream_id']: e for e in g['edges']}; n = N['CRYO_H2']
    n['params']['compressor_design'] = json.loads(json.dumps(r, default=float)); n['params']['compressor'] = f"in-house {r['n_stages']}-stage diaphragm, {DR.val(DR.load(),'h2c_P1_bar'):g} to {DR.val(DR.load(),'h2c_P2_bar'):g} bar, intercooled, {r['units']:g} x 100 % (X-MFG-36)"
    n['continuous_kw'] = {'value': round(r['P_avg_kW'], 4), 'unit': 'kW', 'status': 'study', 'note': f"X-MFG-36 (A-M-169): {r['H2_kg_d']:.2f} kg/d x {r['kWh_per_kg']:.2f} kWh/kg; peak {r['P_peak_kW']:.2f} kW over the run hours."}
    for sid in ('SF-CRYO_H2', 'SQ-CRYO_H2'):
        if sid in E: E[sid]['rate']['value'] = round(r['P_avg_kW'], 4)
    open(GP, 'w').write(json.dumps(g, indent=2))
    d = DR.load(); v = lambda k: DR.val(d, k)
    T1C = v('CRYO.cold-box-asu-recovery-train.cold-box.CRYO_H2.h2c_T_suction_K') - 273.15; units = r['units']
    md = ['# Hydrogen compressor', '', 'Document number: AQS-DUTY-067', 'Revision: C', 'Date: 2026-10-29',
          'Generated by `flow_graph/param/h2_compressor.py` from the plant graph and `flow_graph/param/drivers.json`. Do not edit by hand; change the generator or its inputs and run `python3 -m flow_graph.param.regen`.',
          'Authority: task X-MFG-36 of AQS-PLAN-007; assumption A-M-169. Study. Not a PE stamp.', '',
          '| Rev | Description | Date |', '| --- | --- | --- |',
          '| A | First issue: an in-house diaphragm compressor for the hydrogen store | 2026-10-16 |',
          '| B | Stage count set by the discharge temperature limit; the two-stage layout of Rev A ran too hot | 2026-10-16 |',
          '| C | Record of revisions, purpose and scope added; the design written as sentences; the suction temperature and pressures taken from the drivers in the text | 2026-10-29 |', '',
          '## 1. Purpose and scope', '',
          'This page sizes the in-house multi-stage diaphragm compressor that fills the hydrogen store `CRYO_H2`. It gives the number of stages, the pressures and discharge temperature of each stage, the intercooler duty, the swept volume and diaphragm diameter, and the power. The hydrogen flow is the sum of the mass streams into `CRYO_H2` on the plant graph.', '',
          '## 2. Design', '',
          f"The compressor takes {r['H2_kg_d']:.2f} kg/d of hydrogen from {v('h2c_P1_bar'):g} bar to {v('h2c_P2_bar'):g} bar in {r['n_stages']} stages of equal pressure ratio {r['ratio_per_stage']:.3f}, with an intercooler after each stage that returns the gas to {T1C:.0f} °C. "
          f"The number of stages is the smallest for which the predicted discharge temperature, at an adiabatic efficiency of {v('h2c_eta_ad')}, stays at or below {r['T_limit_C']:.0f} °C, the limit for hydrogen-rich service in [API618]. "
          f"The specific energy is {r['kWh_per_kg']:.2f} kWh/kg, the average power {r['P_avg_kW']:.3f} kW and the peak power over the run hours {r['P_peak_kW']:.3f} kW. "
          + (f"{units:g} compressors are fitted, one of them standby." if isinstance(units, (int, float)) and units > 1 else 'One compressor is fitted.'), '',
          'Table 2.1 gives the stages.', '', 'Table 2.1. Compressor stages', '',
          '| Stage | In bar | Out bar | Discharge °C | Intercooler W (peak) | Swept cm3/stroke | Diaphragm D mm |', '|---|---|---|---|---|---|---|']
    md += [f"| {s['stage']} | {s['P_in_bar']:.1f} | {s['P_out_bar']:.1f} | {s['T_out_C']:.0f} | {s['intercooler_W']:.0f} | {s['swept_cm3']:.1f} | {s['diaphragm_D_mm']:.0f} |" for s in r['stages']]
    md += ['', '## 3. Construction', '',
           'The materials are as follows: ' + r['material'] + '. The intercoolers are 316L tube-in-tube exchangers on the cooling water loop. The efficiencies, the speed and the cavity depth are assumptions until the first article has been run on the bench (A-M-169).']
    open(os.path.join(ROOT, 'docs-authority/sizing/H2_COMPRESSOR.md'), 'w').write('\n'.join(md) + '\n')
def main():
    d = DR.load(); g = json.load(open(GP)); r = design(d, g); print(json.dumps(r, default=float))
    if '--write' in sys.argv: write(g, r)
if __name__ == '__main__': main()
